package dev.veltraph.client.builder;
import org.junit.jupiter.api.Test;
import static org.junit.jupiter.api.Assertions.*;
class Source95PurchaseChooserTest {
 @Test void sourceOneBranchHasPriorityAt16WhenWrapperFlagTrue(){assertEquals(new Source95PurchaseChooser.Choice(Source95PurchaseChooser.Kind.ONE,1),Source95PurchaseChooser.choose(16,true,false,64,0));assertEquals(Source95PurchaseChooser.Kind.STACK,Source95PurchaseChooser.choose(16,false,true,64,10).kind());}
 @Test void fillUsesActualEmptyCapacityAtEqualityAndSpecialBypassesIt(){assertEquals(new Source95PurchaseChooser.Choice(Source95PurchaseChooser.Kind.FILL,128),Source95PurchaseChooser.choose(128,true,false,64,2));assertEquals(Source95PurchaseChooser.Kind.STACK,Source95PurchaseChooser.choose(128,true,true,64,2).kind());assertEquals(new Source95PurchaseChooser.Choice(Source95PurchaseChooser.Kind.FILL,0),Source95PurchaseChooser.choose(128,true,false,64,0));}
 @Test void customIsStrictlyAboveThreeNativeStacksWithRoomAndNonSpecial(){assertEquals(Source95PurchaseChooser.Kind.STACK,Source95PurchaseChooser.choose(192,true,false,64,10).kind());assertEquals(new Source95PurchaseChooser.Choice(Source95PurchaseChooser.Kind.CUSTOM,193),Source95PurchaseChooser.choose(193,true,false,64,10));assertEquals(Source95PurchaseChooser.Kind.STACK,Source95PurchaseChooser.choose(193,true,true,64,10).kind());}
 @Test void source128WithNative64AndRoomSelectsTwoConsecutiveStackLegs(){assertEquals(new Source95PurchaseChooser.Choice(Source95PurchaseChooser.Kind.STACK,64),Source95PurchaseChooser.choose(128,true,false,64,20));assertEquals(new Source95PurchaseChooser.Choice(Source95PurchaseChooser.Kind.STACK,64),Source95PurchaseChooser.choose(64,true,false,64,19));assertEquals(Source95PurchaseChooser.Kind.NONE,Source95PurchaseChooser.choose(0,true,false,64,18).kind());}
 @Test void actualStackSizeChangesChooserAndInvalidCapacityRefuses(){assertEquals(Source95PurchaseChooser.Kind.CUSTOM,Source95PurchaseChooser.choose(128,true,false,32,20).kind());assertThrows(IllegalArgumentException.class,()->Source95PurchaseChooser.choose(128,true,false,0,20));assertThrows(IllegalArgumentException.class,()->Source95PurchaseChooser.choose(128,true,false,64,37));}
}
